   202|    return {
   203|      ok: false,
   204|      status: 'failed',
   205|      region,
   206|      from,
   207|      to,
   208|      missingEnvNames,
   209|      error: error instanceof Error ? error.message : 'SES send request failed.',
   210|      sentAt,
   211|    };
   212|  }
   213|}
